# rpc/parseTRPCMessage.ts:50-84  (rpc.parseTRPCMessage.parseTRPCMessage)
export function parseTRPCMessage(
  obj: unknown,
  transformer: CombinedDataTransformer,
): TRPCClientOutgoingMessage {
  assertIsObject(obj);

  const { id, jsonrpc, method, params } = obj;
  assertIsRequestId(id);
  assertIsJSONRPC2OrUndefined(jsonrpc);

  if (method === 'subscription.stop') {
    return {
      id,
      jsonrpc,
      method,
    };
  }
  assertIsProcedureType(method);
  assertIsObject(params);
  const { input: rawInput, path } = params;

  assertIsString(path);

  const input = transformer.input.deserialize(rawInput);

  return {
    id,
    jsonrpc,
    method,
    params: {
      input,
      path,
    },
  };
}

# rpc/parseTRPCMessage.ts:41-47  (rpc.parseTRPCMessage.assertIsJSONRPC2OrUndefined)
function assertIsJSONRPC2OrUndefined(
  obj: unknown,
): asserts obj is '2.0' | undefined {
  if (typeof obj !== 'undefined' && obj !== '2.0') {
    throw new Error('Must be JSONRPC 2.0');
  }
}

# rpc/parseTRPCMessage.ts:6-10  (rpc.parseTRPCMessage.assertIsObject)
function assertIsObject(obj: unknown): asserts obj is Record<string, unknown> {
  if (typeof obj !== 'object' || Array.isArray(obj) || !obj) {
    throw new Error('Not an object');
  }
}

# rpc/parseTRPCMessage.ts:13-17  (rpc.parseTRPCMessage.assertIsProcedureType)
function assertIsProcedureType(obj: unknown): asserts obj is ProcedureType {
  if (obj !== 'query' && obj !== 'subscription' && obj !== 'mutation') {
    throw new Error('Invalid procedure type');
  }
}

# rpc/parseTRPCMessage.ts:20-31  (rpc.parseTRPCMessage.assertIsRequestId)
function assertIsRequestId(
  obj: unknown,
): asserts obj is number | string | null {
  if (
    obj !== null &&
    typeof obj === 'number' &&
    isNaN(obj) &&
    typeof obj !== 'string'
  ) {
    throw new Error('Invalid request id');
  }
}

# rpc/parseTRPCMessage.ts:34-38  (rpc.parseTRPCMessage.assertIsString)
function assertIsString(obj: unknown): asserts obj is string {
  if (typeof obj !== 'string') {
    throw new Error('Invalid string');
  }
}

